select id, customer_id, device, started_at, country, first_value(browser) ignore nulls over (partition by customer_id order by started_at, id rows between unbounded preceding and current row) as first_known_browser, row_number() over w_ordered as seq_no, row_number() over w_part as row_seq from sessions window w_ordered as (partition by browser order by started_at, id), w_part as (partition by customer_id order by started_at desc, id);
